SourceCode.Declaration:
/// <summary>
/// Parameters of Copy setup. The source is the environment selected in Environments;
/// the user chooses the target environment.
/// </summary>
[DataContractAttribute,
 SysOperationContractProcessingAttribute(classStr(BDRSetupCopyUIBuilder))]
public final class BDRSetupCopyContract implements SysOperationValidatable
{
    private BDREnvironmentId sourceEnvironmentId;
    private BDREnvironmentId targetEnvironmentId;
    private NoYes replaceExisting;
}

Method.Source:
[DataMemberAttribute('SourceEnvironmentId'),
 SysOperationControlVisibilityAttribute(false)]
public BDREnvironmentId parmSourceEnvironmentId(BDREnvironmentId _sourceEnvironmentId = sourceEnvironmentId)
{
    sourceEnvironmentId = _sourceEnvironmentId;
    return sourceEnvironmentId;
}

[DataMemberAttribute('TargetEnvironmentId'),
 SysOperationLabelAttribute(literalStr("@BDR:TargetEnvironment")),
 SysOperationDisplayOrderAttribute('1')]
public BDREnvironmentId parmTargetEnvironmentId(BDREnvironmentId _targetEnvironmentId = targetEnvironmentId)
{
    targetEnvironmentId = _targetEnvironmentId;
    return targetEnvironmentId;
}

[DataMemberAttribute('ReplaceExisting'),
 SysOperationLabelAttribute(literalStr("@BDR:ReplaceExisting")),
 SysOperationHelpTextAttribute(literalStr("@BDR:ReplaceExistingHelp")),
 SysOperationDisplayOrderAttribute('2')]
public NoYes parmReplaceExisting(NoYes _replaceExisting = replaceExisting)
{
    replaceExisting = _replaceExisting;
    return replaceExisting;
}

    public boolean validate()
    {
        boolean ret = true;

        if (!BDREnvironment::exist(sourceEnvironmentId))
        {
            ret = checkFailed("@BDR:ErrOpenFromEnvironment");
        }

        if (!BDREnvironment::exist(targetEnvironmentId))
        {
            ret = checkFailed(strFmt("@BDR:ErrUnknownEnvironment", targetEnvironmentId));
        }

        if (sourceEnvironmentId == targetEnvironmentId)
        {
            ret = checkFailed("@BDR:ErrCopySame");
        }

        return ret;
    }
